sp_widget.client_script:
function loginCtrl($scope, $http, $window, $location, glideUserSession, glideSystemProperties, spUtil) {

	var c = this;


	// ==========================================
	// INITIAL SETTINGS
	// ==========================================

	c.remember_me =
		c.data.forgetMe ?
		false :
		c.data.rememberMeDefault;

	c.data.url_suffix =
		$scope.portal ?
		$scope.portal.url_suffix :
		"";

	c.masked = true;


	// ==========================================
	// SSO LOGIN
	// ==========================================

	if (!c.data.is_logged_in &&
		c.data.multisso_enabled &&
		c.data.default_idp) {

		var pageId =
			$location.search().id ||
			$scope.page.id;

		var isLoginPage =
			($scope.portal.login_page_dv == pageId) ||
			('login' == pageId);

		c.server.get({

			action: "set_sso_destination",

			pageURI:
				isLoginPage ?
				null :
				$location.url()

		}).then(function() {

			$window.location =
				"/login_with_sso.do?glide_sso_id=" +
				c.data.default_idp;

		});

	}


	// ==========================================
	// CERTIFICATE LOGIN
	// ==========================================

	else if (
		!c.data.is_logged_in &&
		c.data.certAuthRedirect &&
		c.data.cert_based_auth &&
		c.data.certHeader == "true"
	) {

		login(null, null, true);

	}


	// ==========================================
	// LOGIN BUTTON
	// ==========================================

	c.login = function(username, password, isCertLogin) {

		login(
			username,
			password,
			isCertLogin
		);

	};


	// ==========================================
	// LOGIN FUNCTION
	// ==========================================

	function login(username, password, isCertLogin) {

		var url =
			spUtil.getURL({
				sysparm_type:
					'view_form.login'
			});


		var pageId =
			$location.search().id ||
			$scope.page.id;


		var isLoginPage =
			($scope.portal.login_page_dv == pageId) ||
			('login' == pageId);


		return $http({

			method: 'post',

			url: url,

			data: $.param({

				'sysparm_type':
					'login',

				'ni.nolog.user_password':
					true,

				'remember_me':
					!!c.remember_me,

				'user_name':
					username,

				'user_password':
					password,

				'get_redirect_url':
					true,

				'is_direct_redirect':
					true,

				'sysparm_goto_url':
					isLoginPage ?
					null :
					$location.url(),

				'mfa_redirect_url':
					isLoginPage ?
					null :
					c.data.pageURI,

				'cert_login':
					!!isCertLogin

			}),

			headers: {

				'Content-Type':
					'application/x-www-form-urlencoded'

			}

		}).then(function(response) {


			// ======================================
			// EMPTY RESPONSE
			// ======================================

			if (!response.data) {

				c.message =
					$scope.data.errorMsg;

				return;

			}


			// ======================================
			// SUCCESSFUL LOGIN
			// ======================================

			if (response.data.status == 'success') {


				// MFA enabled
				if (c.data.multiFactorAuthEnabled) {


					if (response.data.session_token) {

						window.g_ck =
							response.data.session_token;

					}


					c.server.get({

						action:
							"multi_factor_auth_setup",

						directTo:
							response.data.redirect_url

					}).then(

						handleLoginResponse.bind(response),

						handleLoginResponse.bind(response)

					);

				}


				// Normal login
				else {

					handleLoginResponse.call(response);

				}

			}


			// ======================================
			// MFA CODE REQUIRED
			// ======================================

			else if (
				response.data.status ==
				'mfa_code_required'
			) {

				$window.location =
					'/validate_multifactor_auth_code.do';

			}


			// ======================================
			// LOGIN FAILED
			// ======================================

			else {

				c.message =
					response.data.message ||
					"Invalid username or password.";

				c.password = "";

				c.username = "";

				setTimeout(function() {

					var usernameElement =
						document.getElementById(
							"username"
						);

					if (usernameElement) {

						usernameElement.focus();

					}

				}, 100);

			}


		}, function errorCallback(response) {

			c.message =
				$scope.data.errorMsg ||
				"Unable to process login.";

		});

	}


	// ==========================================
	// LOGIN SUCCESS RESPONSE
	// ==========================================

	function handleLoginResponse() {

		c.success =
			this.data.message;


		/*
		 * IMPORTANT:
		 *
		 * Do NOT use:
		 *
		 * $window.location =
		 * this.data.redirect_url;
		 *
		 * We want the Insurance Claim Hub
		 * home page every time.
		 */


		var portalSuffix =
			c.data.url_suffix ||
			($scope.portal ?
				$scope.portal.url_suffix :
				"");


		var homeUrl;


		if (portalSuffix) {

			homeUrl =
				"/" +
				portalSuffix +
				"?id=claim_home";

		} else {

			homeUrl =
				"?id=claim_home";

		}


		// Force navigation to claim_home

		$window.location.href =
			homeUrl;

	}


	// ==========================================
	// OIDC LOGIN
	// ==========================================

	c.oidcLogin = function(idProvider) {

		var pageId =
			$location.search().id ||
			$scope.page.id;

		var isLoginPage =
			$scope.portal.login_page_dv ==
			pageId;


		c.server.get({

			action:
				"set_sso_destination",

			pageURI:
				isLoginPage ?
				null :
				$location.url()

		}).then(function() {

			$window.location =
				"/login_with_sso.do?glide_sso_id=" +
				idProvider;

		});

	};


	// ==========================================
	// EXTERNAL LOGIN
	// ==========================================

	c.externalLogin = function() {

		var pageId =
			$location.search().id ||
			$scope.page.id;


		var isLoginPage =
			($scope.portal.login_page_dv == pageId) ||
			('login' == pageId);


		c.server.get({

			action:
				"set_sso_destination",

			pageURI:
				isLoginPage ?
				null :
				$location.url()

		}).then(function() {

			glideSystemProperties.set(
				"glide.authenticate.multisso.enabled",
				true
			);


			glideUserSession
				.getSsoRedirectUrlForUsername(
					c.username
				)
				.then(function(url) {

					$window.location =
						url;

				}, function(err) {

					spUtil.addErrorMessage(
						$scope.data.errorMsg2
					);

				});

		});

	};


	// ==========================================
	// EXTERNAL LOGIN MODE
	// ==========================================

	c.setExternalLogin = function(newVal) {

		c.externalLoginMode =
			newVal;


		if (!newVal) {

			c.masked = true;

		}

	};


	// ==========================================
	// PASSWORD SHOW / HIDE
	// ==========================================

	c.renderMaskIcon = function() {

		var passwordEle =
			document.getElementById(
				"password"
			);

		var maskEle =
			document.getElementById(
				"mask_icon"
			);

		var btnDescription =
			document.getElementById(
				"btnDescription"
			);


		if (!passwordEle) {
			return;
		}


		var isPasswordType =
			passwordEle.type ===
			'password';


		if (maskEle) {

			maskEle.classList.toggle(
				'active',
				isPasswordType
			);

		}


		passwordEle.type =
			isPasswordType ?
			'text' :
			'password';


		if (btnDescription) {

			btnDescription.textContent =
				isPasswordType ?
				'Password shown' :
				'Password hidden';

		}

	};


	// ==========================================
	// CREATE ACCOUNT
	// ==========================================

	c.goToSignup = function() {

		$location.search({

			id: "claim_signup"

		});

	};

}

sp_widget.css:
/* ==========================================
   LOGIN PAGE
   ========================================== */

.ich-login-page {

    min-height: 100vh;

    display: flex;

    align-items: center;

    justify-content: center;

    position: relative;

    overflow: hidden;

    padding: 35px 20px;

    box-sizing: border-box;

    background:
        linear-gradient(
            135deg,
            #edf6ff 0%,
            #f8fbff 50%,
            #edf3ff 100%
        );

}


/* ==========================================
   BACKGROUND
   ========================================== */

.ich-bg-circle {

    position: absolute;

    border-radius: 50%;

    pointer-events: none;

}


.ich-circle-one {

    width: 430px;

    height: 430px;

    top: -220px;

    left: -140px;

    background:
        rgba(37, 99, 235, 0.08);

}


.ich-circle-two {

    width: 380px;

    height: 380px;

    right: -150px;

    bottom: -200px;

    background:
        rgba(59, 130, 246, 0.07);

}


/* ==========================================
   LOGIN CARD
   ========================================== */

.ich-login-card {

    width: 100%;

    max-width: 440px;

    padding: 38px 42px 28px;

    background: #ffffff;

    border-radius: 20px;

    border: 1px solid #e4ebf4;

    box-shadow:
        0 25px 70px
        rgba(30, 64, 175, 0.14);

    position: relative;

    z-index: 2;

    box-sizing: border-box;

}


/* ==========================================
   BRAND
   ========================================== */

.ich-brand {

    text-align: center;

    margin-bottom: 28px;

}


.ich-logo {

    width: 68px;

    height: 68px;

    margin: 0 auto 14px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 18px;

    font-size: 32px;

    background:
        linear-gradient(
            135deg,
            #0757c9,
            #2486e8
        );

    box-shadow:
        0 12px 28px
        rgba(37, 99, 235, 0.25);

}


.ich-brand h1 {

    margin: 0;

    color: #12315b;

    font-size: 25px;

    font-weight: 700;

    letter-spacing: -0.4px;

}


.ich-brand p {

    margin: 6px 0 0;

    color: #718198;

    font-size: 12px;

}


/* ==========================================
   WELCOME
   ========================================== */

.ich-welcome {

    text-align: center;

    margin-bottom: 25px;

}


.ich-welcome h2 {

    margin: 0;

    color: #16365f;

    font-size: 22px;

    font-weight: 700;

}


.ich-welcome p {

    margin: 7px auto 0;

    max-width: 320px;

    color: #7b8ca2;

    font-size: 13px;

    line-height: 1.5;

}


/* ==========================================
   FORM
   ========================================== */

.ich-field {

    margin-bottom: 18px;

}


.ich-field label {

    display: block;

    margin-bottom: 8px;

    color: #344a68;

    font-size: 12px;

    font-weight: 600;

}


.ich-password-label {

    display: flex;

    justify-content: space-between;

    align-items: center;

}


.ich-password-label label {

    margin-bottom: 8px;

}


.ich-password-label a {

    color: #1769d1;

    font-size: 11px;

    text-decoration: none;

}


.ich-password-label a:hover {

    text-decoration: underline;

}


/* ==========================================
   INPUT
   ========================================== */

.ich-input-wrapper {

    position: relative;

}


.ich-input-icon {

    position: absolute;

    left: 14px;

    top: 50%;

    transform: translateY(-50%);

    font-size: 15px;

    opacity: 0.65;

    pointer-events: none;

}


.ich-input {

    width: 100%;

    height: 48px;

    padding:
        0 14px 0 43px;

    border:
        1px solid #d5dfeb;

    border-radius: 9px;

    background: #f8fbff;

    color: #263d5c;

    font-size: 13px;

    outline: none;

    box-sizing: border-box;

    transition:
        border 0.2s,
        box-shadow 0.2s,
        background 0.2s;

}


.ich-input::placeholder {

    color: #a0adbc;

}


.ich-input:focus {

    background: #ffffff;

    border-color: #2774d7;

    box-shadow:
        0 0 0 3px
        rgba(39, 116, 215, 0.10);

}


/* ==========================================
   REMEMBER ME
   ========================================== */

.ich-options {

    margin:
        2px 0 18px;

}


.ich-remember {

    display: flex;

    align-items: center;

    gap: 7px;

    color: #718198;

    font-size: 11px;

    cursor: pointer;

}


.ich-remember input {

    width: 14px;

    height: 14px;

    accent-color: #1769d1;

}


/* ==========================================
   LOGIN BUTTON
   ========================================== */

.ich-login-btn {

    width: 100%;

    height: 49px;

    border: none;

    border-radius: 9px;

    background:
        linear-gradient(
            135deg,
            #1467d5,
            #2582e3
        );

    color: #ffffff;

    font-size: 14px;

    font-weight: 700;

    cursor: pointer;

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 10px;

    box-shadow:
        0 9px 22px
        rgba(37, 99, 235, 0.22);

    transition:
        transform 0.2s,
        box-shadow 0.2s;

}


.ich-login-btn:hover {

    transform: translateY(-1px);

    box-shadow:
        0 12px 27px
        rgba(37, 99, 235, 0.28);

}


.ich-arrow {

    font-size: 18px;

}


/* ==========================================
   ERROR MESSAGE
   ========================================== */

.ich-message {

    margin-top: 13px;

    padding: 10px 12px;

    border-radius: 7px;

    background: #fff1f2;

    border: 1px solid #fecdd3;

    color: #be123c;

    text-align: center;

    font-size: 12px;

}


/* ==========================================
   DIVIDER
   ========================================== */

.ich-divider {

    display: flex;

    align-items: center;

    gap: 10px;

    margin: 25px 0 17px;

    color: #9aa8b8;

    font-size: 10px;

}


.ich-divider::before,
.ich-divider::after {

    content: "";

    flex: 1;

    height: 1px;

    background: #e7edf3;

}


.ich-divider span {

    white-space: nowrap;

}


/* ==========================================
   SIGNUP BUTTON
   ========================================== */

.ich-signup-btn {

    width: 100%;

    height: 46px;

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 8px;

    border:
        1px solid #2471d5;

    border-radius: 9px;

    background: #ffffff;

    color: #1769d1;

    font-size: 13px;

    font-weight: 600;

    cursor: pointer;

    transition:
        background 0.2s,
        border 0.2s;

}


.ich-signup-btn:hover {

    background: #f0f6ff;

    border-color: #145db8;

}


.ich-signup-btn span:last-child {

    font-size: 17px;

}


/* ==========================================
   SECURITY
   ========================================== */

.ich-security {

    display: flex;

    justify-content: center;

    align-items: center;

    gap: 6px;

    margin-top: 21px;

    padding-top: 17px;

    border-top: 1px solid #edf1f5;

    color: #8b99aa;

    font-size: 10px;

}


/* ==========================================
   FOOTER
   ========================================== */

.ich-footer {

    text-align: center;

    margin-top: 13px;

    color: #b2bcc8;

    font-size: 9px;

}


/* ==========================================
   MOBILE
   ========================================== */

@media (max-width: 500px) {

    .ich-login-page {

        padding:
            20px 12px;

    }


    .ich-login-card {

        padding:
            30px 24px 24px;

        border-radius: 17px;

    }


    .ich-brand h1 {

        font-size: 22px;

    }

}

sp_widget.script:
(function() {
    options.show_panel = options.show_panel == "true" || options.show_panel == true;

    if (input && input.action === "multi_factor_auth_setup") {
        if (gs.getSession().getProperty("setup_multifactor_authn")) {
            if (input.directTo && input.directTo != "/login_cpw.do") {
              gs.getSession().putProperty("nav_to", input.directTo);
              gs.getSession().putProperty("starting_page", input.directTo);
            }
            gs.getSession().putProperty("is_direct_redirect", "true");
        }
        return;
    }
    var portalRecord = $sp.getPortalRecord();
    var idpList = [];
    data.isMultiSSOActive = gs.getProperty('glide.authenticate.multisso.enabled', 'false') == 'true';

    if (data.isMultiSSOActive) {
        data.portal_authentication_mode = $sp.getValue("enable_portal_authentication") == 'true';
        data.use_local_login = $sp.getValue("enable_local_login") == 'true';
        var portalIdentityProviders = $sp.getValue('portal_identity_providers');
        if (data.portal_authentication_mode && portalIdentityProviders) {
            var arr = portalIdentityProviders.split(',');
            for (var i = 0; i < arr.length; i++) {
                var val = arr[i];
                if (val) idpList.push(val.trim() + "");
            }
        }
    }


    var ssoSelectorField = gs.getProperty('glide.authenticate.multisso.login_locate.user_field', 'user_name');
    var td = new GlideTableDescriptor('sys_user');
    var ed = td.getElementDescriptor(ssoSelectorField);
    if (ed)
        data.ssoSelectorFieldLabel = ed.getLabel();


    // We don't want to set a starting page until we've begun the login process.
    if (input && input.action === "set_sso_destination") {
        var gs_nav_to = gs.getSession().getProperty("nav_to");
        gs.getSession().putProperty("nav_to", null);

        if (input.pageURI) {
            gs.getSession().putProperty("is_direct_redirect", "true");
            gs.getSession().putProperty("starting_page", input.pageURI);
        } else if (!gs.getSession().getProperty("starting_page") && gs_nav_to)
            gs.getSession().putProperty("starting_page", gs_nav_to);
        return;

    }

    // for self registration fields
    var self_registration_field = portalRecord ? portalRecord.getValue("user_registration_config") : "";
    if (self_registration_field) {
        var registration_config = new GlideRecord("sys_user_registration_config");
        registration_config.addActiveQuery();
        registration_config.query('sys_id', self_registration_field);
        if (registration_config.next()) {
            var self_registration_record_producer = registration_config.getValue("record_producer");
            var self_registration_label = registration_config.getDisplayValue("registration_label") || gs.getMessage("Sign Up");
            data.self_registration_record_producer = self_registration_record_producer;
            data.self_registration_label = self_registration_label;
        }
    }

    //Enabling certificate based authentication per portal
    if (portalRecord && (portalRecord.getValue('enable_certificate_based_authentication') == 1))
        data.cert_based_auth = gs.getProperty('glide.authenticate.mutual.enabled', 'false') == 'true';

    //get the certificate header
    if (data.cert_based_auth) {
	var request = GlideTransaction.get().getRequest();
	var certHeader = request.getHeader("X-Client-Cert");
	if (!certHeader) {
		data.certHeader = "false";
            gs.log("Failed to register PIV/CAC certificate to the user account.");
        } else
		data.certHeader = "true";    
    }

    //Get the OpenID Connect and SAML type Identity provider which can be shown on the Portal login page.
    data.isShowLoginWithIdps = false;
    data.isMultiSSOActive = gs.getProperty('glide.authenticate.multisso.enabled', 'false') == 'true';
    var ssoRecords = [];
    data.ssoRecords = [];

    var gr = new GlideRecord("sso_properties");
    if (data.isMultiSSOActive && gr.isValid()) {
        ssoRecords = new MultiSSO_OidcUtil().getSSORecords();
    }

    if (!data.portal_authentication_mode) {
        data.ssoRecords = ssoRecords;
    } else if (idpList.length > 0) {
        for (var i = 0; i < ssoRecords.length; i++) {
            var idp = ssoRecords[i];
            if (idpList.indexOf(idp.sysId.trim()) !== -1)
                data.ssoRecords.push(idp);
        }
    }
    data.isShowLoginWithIdps = (data.ssoRecords.length > 0);

    //STRY50033370: Forgot Password link in the login widget
    data.pswdResetUrl = gs.getProperty('glide.security.password_reset.uri');
    data.forgotPwdLinkProp = gs.getProperty('glide.security.forgot_password.display.link');

    data.errorMsg = gs.getMessage("There was an error processing your request");
    data.errorMsg2 = gs.getMessage("An error has occurred - please contact your system administrator");
    data.passwordMsg = gs.getMessage("Password");
    data.usernameMsg = gs.getMessage("User name");
    data.forgetMe = GlideProperties.getBoolean("glide.ui.forgetme");
    data.rememberMeDefault = GlideProperties.getBoolean('glide.ui.remember.me.default', true);
    data.is_logged_in = gs.getSession().isLoggedIn();
    var bypass_sso = options.bypass_sso == "true";
    data.multisso_enabled = !bypass_sso && GlideProperties.getBoolean("glide.authenticate.multisso.enabled");
    data.default_idp = GlideProperties.get("glide.authenticate.sso.redirect.idp");
    data.pageURI = new GlideSPUtil().getPageUri();
    data.multiFactorAuthEnabled = GlideProperties.getBoolean('glide.authenticate.multifactor', false);
    data.certAuthRedirect = gs.getProperty('glide.authenticate.cert.redirect.enable', 'false') == 'true';
    if (data.portal_authentication_mode && data.use_local_login)
        data.default_idp = null;
    if (data.portal_authentication_mode && data.ssoRecords.length > 0) {
        if (data.ssoRecords.length == 1)
            data.default_idp = data.ssoRecords[0].sysId;
        else if (data.ssoRecords.length > 1)
            data.default_idp = null;

    }

    //STRY53144967: Handle user redirection to specific Identity provider mapped in Custom Url record for Portals
    var customURL = GlideProperties.getBoolean('glide.customurl.enabled', false);
    if (customURL == true && data.multisso_enabled == true) {
		var idp = SNC.CustomURLSPUtil.getAutoRedirectIDPForCustomURLWithPortal();
		if(GlideStringUtil.notNil(idp))
			data.default_idp = idp;
    }

	//Show info message is session access is reduced
    var isSessionAccessReduced = GlideSession.get().getBooleanProperty("isSessionAccessReduced", false);
    var isSessionAccessMessageShown = GlideSession.get().getBooleanProperty("isSessionAccessReducedMessageShown", false);
    if (isSessionAccessReduced && !isSessionAccessMessageShown)
        SNC.SessionAccessUtil.showUserInfoMessageIfAccessReduced();
})();
